INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('b92966da-c385-5692-a57a-55377cf6a39c', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 7, 7, 'What causes a Hall voltage across a current-carrying slab in a magnetic field?', NULL, 1, 'multiple_choice'::answer_type, 'The magnetic force pushes the moving charge carriers to one side of the slab', NULL, false, NULL, false, NULL, 'Charge builds up on one face, giving a p.d. across the slab. Mark scheme (1 mark). B1: C (The magnetic force pushes the moving charge carriers to one side of the slab).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 256" role="img" aria-labelledby="fgc34d3fb7-t fgc34d3fb7-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgc34d3fb7-t">Hall slab</title><desc id="fgc34d3fb7-d">Top view of a thin slab carrying a current I along its length in a magnetic field into the page; a voltmeter is connected across the width of the slab.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><line x1="20" y1="232" x2="28" y2="240" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="240" x2="28" y2="232" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B into the page</text></svg>', 'Top view of a thin slab carrying a current I along its length in a magnetic field into the page; a voltmeter is connected across the width of the slab.'),
('938c1b89-d5ad-5820-9f63-458c3512a361', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 8, 8, 'A Hall probe gives 0.40 mV in a certain field. The flux density is doubled, with the same current. What is the new Hall voltage, in mV?', NULL, 1, 'numeric'::answer_type, '0.8 mV', 'mV', false, NULL, false, NULL, 'V_H ∝ B: 2 × 0.40 = 0.80 mV. Mark scheme (2 marks). C1: V_H ∝ B. A1: V_H = 0.80 mV.', 2, NULL, NULL),
('ea20273a-8960-5975-b53b-599fa4656106', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 9, 9, 'With a constant current, which describes a graph of Hall voltage against magnetic flux density?', NULL, 1, 'multiple_choice'::answer_type, 'A straight line through the origin', NULL, false, NULL, false, NULL, 'V_H = BI/ntq, so V_H ∝ B. Mark scheme (1 mark). B1: A (A straight line through the origin).', 1, NULL, NULL),
('c140a13e-c35b-55fe-aa0f-fb0d6474bc87', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 10, 10, 'A semiconductor slice has 1.0 × 10²² charge carriers per m³ and is 1.0 mm thick. It carries 10 mA in a field of 0.10 T. Calculate the Hall voltage, in mV, using V_H = BI/ntq. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '0.625 mV', 'mV', false, NULL, false, NULL, 'V_H = 0.10 × 10 × 10⁻³ ÷ (1.0 × 10²² × 1.0 × 10⁻³ × 1.60 × 10⁻¹⁹) = 6.25 × 10⁻⁴ V. In mV: 6.250 × 10⁻⁴ × 1000 = 0.625. Mark scheme (2 marks). C1: V_H = BI/ntq. A1: V_H = 0.625 mV.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 296" role="img" aria-labelledby="fgbf6754f9-t fgbf6754f9-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgbf6754f9-t">Semiconductor Hall slice</title><desc id="fgbf6754f9-d">A semiconductor slice 1.0 mm thick with 1.0 × 10²² charge carriers per m³ carries 10 mA in a 0.10 T field into the page; the Hall voltage is measured across its width.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I = 10 mA</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thickness 1.0 mm</text><text x="110" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">1.0 × 10²² carriers per m³</text><line x1="20" y1="272" x2="28" y2="280" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="280" x2="28" y2="272" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="276" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.10 T</text></svg>', 'A semiconductor slice 1.0 mm thick with 1.0 × 10²² charge carriers per m³ carries 10 mA in a 0.10 T field into the page; the Hall voltage is measured across its width.'),
('d7c3583f-476b-5a9b-af47-13dddccfaec7', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 11, 11, 'Why are Hall probes made as thin slices?', NULL, 1, 'multiple_choice'::answer_type, 'The Hall voltage is inversely proportional to the thickness, so a thin slice gives a larger voltage', NULL, false, NULL, false, NULL, 'V_H = BI/ntq, so for a given B and I the Hall voltage is inversely proportional to the thickness t. Mark scheme (1 mark). B1: D (The Hall voltage is inversely proportional to the thickness, so a thin slice gives a larger voltage).', 1, NULL, NULL),
('933f09fc-07b5-5fac-aaa7-f504e02b9b06', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 12, 12, 'A Hall probe gives 5.0 mV in a field of 0.20 T. In another field, with the same current, it gives 12.5 mV. Calculate this field.', NULL, 1, 'numeric'::answer_type, '0.5', 'T', false, NULL, false, NULL, 'B ∝ V_H: B = 0.20 × 12.5 ÷ 5.0 = 0.50 T. Mark scheme (2 marks). C1: proportionality. A1: B = 0.50 T.', 2, NULL, NULL),
('6f16dc21-d05d-5210-a24b-718a6908a4d2', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 13, 13, 'How should a Hall probe be held to give the largest reading?', NULL, 1, 'multiple_choice'::answer_type, 'With its flat face at right angles to the magnetic field', NULL, false, NULL, false, NULL, 'Only the field component perpendicular to the slice deflects the carriers across it. Mark scheme (1 mark). B1: B (With its flat face at right angles to the magnetic field).', 1, NULL, NULL),
('70416106-69c9-5f20-bd7d-e3633742f56f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 14, 14, 'A copper wire of cross-sectional area 1.0 × 10⁻⁶ m² carries 2.0 A. Copper has 8.5 × 10²⁸ free electrons per m³. Calculate the drift speed of the electrons. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '1.471e-4', 'm s⁻¹', false, NULL, false, NULL, 'v = I/(nAq) = 2.0 ÷ (8.5 × 10²⁸ × 1.0 × 10⁻⁶ × 1.60 × 10⁻¹⁹) = 1.47 × 10⁻⁴ m s⁻¹. Mark scheme (2 marks). C1: I = nAvq. A1: v = 1.47 × 10⁻⁴ m s⁻¹.', 2, NULL, NULL),
('64d05774-0d89-54c0-9f60-61fb8cbc3b2b', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 15, 15, 'What can the sign of the Hall voltage tell us about a material?', NULL, 1, 'multiple_choice'::answer_type, 'Whether its charge carriers are positive or negative', NULL, false, NULL, false, NULL, 'Positive and negative carriers moving to give the same current are pushed to the same side, giving opposite polarities. Mark scheme (1 mark). B1: C (Whether its charge carriers are positive or negative).', 1, NULL, NULL),
('baa865ba-cc26-562f-85fd-39ed6f8a26da', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 16, 16, 'Charge carriers drift at 0.20 m s⁻¹ through a semiconductor slice 5.0 mm wide in a field of 0.40 T. Using E_H = vB, calculate the Hall voltage across the slice, in mV.', NULL, 1, 'numeric'::answer_type, '0.4 mV', 'mV', false, NULL, false, NULL, 'E_H = vB = 0.20 × 0.40 = 0.080 V m⁻¹. V_H = E_H × width = 0.080 × 5.0 × 10⁻³ = 4.0 × 10⁻⁴ V. In mV: 4.0 × 10⁻⁴ × 1000 = 0.40. Mark scheme (2 marks). C1: E_H = vB then × width. A1: V_H = 0.40 mV.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 256" role="img" aria-labelledby="fg4376c2e2-t fg4376c2e2-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg4376c2e2-t">Hall slice</title><desc id="fg4376c2e2-d">A semiconductor slice 5.0 mm wide in a 0.40 T field into the page; its charge carriers drift along it at 0.20 m s⁻¹ and the Hall voltage appears across the width.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">carriers drift at 0.20 m s⁻¹</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><polygon points="92,80 95,86.3 89,86.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="92" y1="84.9" x2="92" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="92,170 89,163.7 95,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="86" y="125" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">5.0 mm</text><line x1="20" y1="232" x2="28" y2="240" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="240" x2="28" y2="232" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.40 T</text></svg>', 'A semiconductor slice 5.0 mm wide in a 0.40 T field into the page; its charge carriers drift along it at 0.20 m s⁻¹ and the Hall voltage appears across the width.'),
('709e9d1a-5cbd-54a9-bf4a-38e37a43fcba', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 17, 17, 'Why is the Hall voltage in a metal very small?', NULL, 1, 'multiple_choice'::answer_type, 'Metals have a very large number of free electrons per m³, so they drift very slowly', NULL, false, NULL, false, NULL, 'V_H = BI/ntq: a large n gives a small V_H. Mark scheme (1 mark). B1: A (Metals have a very large number of free electrons per m³, so they drift very slowly).', 1, NULL, NULL),
('4f1d3c46-7dcc-5efb-80ea-840e1f3e9620', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 18, 18, 'A Hall probe gives 3.0 mV with a probe current of 20 mA. What does it give, in the same field, with a current of 30 mA, in mV?', NULL, 1, 'numeric'::answer_type, '4.5 mV', 'mV', false, NULL, false, NULL, 'V_H ∝ I: 3.0 × 30 ÷ 20 = 4.5 mV. Mark scheme (1 mark). A1: V_H = 4.5 mV.', 1, NULL, NULL),
('c188eacf-3136-5652-9b2b-e42f88d7622c', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 19, 19, 'In the steady state in a Hall probe, which forces on a moving charge carrier are balanced?', NULL, 1, 'multiple_choice'::answer_type, 'The magnetic force Bqv and the electric force qE_H from the Hall field', NULL, false, NULL, false, NULL, 'Carriers then flow straight along the slice: qE_H = Bqv. Mark scheme (1 mark). B1: D (The magnetic force Bqv and the electric force qE_H from the Hall field).', 1, NULL, NULL),
('4ab7a058-fd20-53cf-81cb-f798813a86a6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 20, 20, 'A Hall probe 0.50 mm thick carries 20 mA in a field of 0.50 T and gives a Hall voltage of 2.5 mV. Calculate the number of charge carriers per m³. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '5e22', 'm⁻³', false, NULL, false, NULL, 'n = BI/(V_H t q) = 0.50 × 0.020 ÷ (2.5 × 10⁻³ × 0.50 × 10⁻³ × 1.60 × 10⁻¹⁹) = 5.0 × 10²² m⁻³. Mark scheme (2 marks). C1: rearranged V_H = BI/ntq. A1: n = 5.0 × 10²² m⁻³.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 296" role="img" aria-labelledby="fgf1d29e67-t fgf1d29e67-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgf1d29e67-t">Hall probe</title><desc id="fgf1d29e67-d">A Hall probe 0.50 mm thick carrying 20 mA in a 0.50 T field into the page gives a Hall voltage of 2.5 mV across its width.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I = 20 mA</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thickness 0.50 mm</text><text x="110" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">Hall voltage 2.5 mV</text><line x1="20" y1="272" x2="28" y2="280" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="280" x2="28" y2="272" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="276" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.50 T</text></svg>', 'A Hall probe 0.50 mm thick carrying 20 mA in a 0.50 T field into the page gives a Hall voltage of 2.5 mV across its width.'),
('e50801b1-34d4-5ab3-b95d-f01558fb4dee', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 21, 21, 'Why must the current through a Hall probe be kept constant while it is used?', NULL, 1, 'multiple_choice'::answer_type, 'The Hall voltage is proportional to the current as well as to B', NULL, false, NULL, false, NULL, 'V_H = BI/ntq: a change in I would be mistaken for a change in B. Mark scheme (1 mark). B1: B (The Hall voltage is proportional to the current as well as to B).', 1, NULL, NULL),
('69f1f3bc-2184-5248-b845-58fda06dcbc0', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 22, 22, 'A copper strip 0.10 mm thick carries 5.0 A at right angles to a 1.0 T field. Copper has 8.5 × 10²⁸ free electrons per m³. Calculate the Hall voltage, in µV. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '3.676 uV', 'µV', false, NULL, false, NULL, 'V_H = BI/ntq = 1.0 × 5.0 ÷ (8.5 × 10²⁸ × 0.10 × 10⁻³ × 1.60 × 10⁻¹⁹) = 3.68 × 10⁻⁶ V. In µV: 3.676 × 10⁻⁶ × 10⁶ = 3.68. Mark scheme (2 marks). C1: V_H = BI/ntq. A1: V_H = 3.68 µV.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 296" role="img" aria-labelledby="fg3951d505-t fg3951d505-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg3951d505-t">Copper strip</title><desc id="fg3951d505-d">A copper strip 0.10 mm thick carrying 5.0 A at right angles to a 1.0 T field (into the page); copper has 8.5 × 10²⁸ free electrons per m³.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I = 5.0 A</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thickness 0.10 mm</text><text x="110" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">8.5 × 10²⁸ free electrons per m³</text><line x1="20" y1="272" x2="28" y2="280" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="280" x2="28" y2="272" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="276" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 1.0 T</text></svg>', 'A copper strip 0.10 mm thick carrying 5.0 A at right angles to a 1.0 T field (into the page); copper has 8.5 × 10²⁸ free electrons per m³.'),
('85c65930-2177-5510-b020-552a6b9f384d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 23, 23, 'The magnetic field through a Hall probe is reversed. What happens to the Hall voltage?', NULL, 1, 'multiple_choice'::answer_type, 'It reverses polarity but keeps the same size', NULL, false, NULL, false, NULL, 'The carriers are pushed to the opposite face. Mark scheme (1 mark). B1: C (It reverses polarity but keeps the same size).', 1, NULL, NULL),
('268349c3-8efb-50fc-ad45-01187298fe20', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 24, 24, 'A Hall probe gives 0.150 V in a field of 0.30 T. With the same current, it gives 0.085 V in an unknown field. Calculate the unknown flux density.', NULL, 2, 'numeric'::answer_type, '0.17', 'T', false, NULL, false, NULL, 'B ∝ V_H: B = 0.30 × 0.085 ÷ 0.150 = 0.170 T. Mark scheme (3 marks). C1: V_H ∝ B. C1: substitution. A1: B = 0.170 T.', 3, NULL, NULL),
('cb0fc401-4a2d-5953-a381-d0a80402d10e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 25, 25, 'A semiconductor Hall probe has 2.0 × 10²¹ carriers per m³ and is 0.20 mm thick. It carries 5.0 mA in a field of 0.25 T. Calculate the Hall voltage, in mV. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '19.53 mV', 'mV', false, NULL, false, NULL, 'V_H = 0.25 × 5.0 × 10⁻³ ÷ (2.0 × 10²¹ × 0.20 × 10⁻³ × 1.60 × 10⁻¹⁹) = 0.0195 V. In mV: 0.01953 × 1000 = 19.5. Mark scheme (4 marks). C1: V_H = BI/ntq. C1: units converted. C1: value. A1: V_H = 19.5 mV.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 296" role="img" aria-labelledby="fg379b2d31-t fg379b2d31-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg379b2d31-t">Semiconductor Hall probe</title><desc id="fg379b2d31-d">A semiconductor Hall probe 0.20 mm thick with 2.0 × 10²¹ carriers per m³ carrying 5.0 mA in a 0.25 T field into the page.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I = 5.0 mA</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thickness 0.20 mm</text><text x="110" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">2.0 × 10²¹ carriers per m³</text><line x1="20" y1="272" x2="28" y2="280" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="280" x2="28" y2="272" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="276" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.25 T</text></svg>', 'A semiconductor Hall probe 0.20 mm thick with 2.0 × 10²¹ carriers per m³ carrying 5.0 mA in a 0.25 T field into the page.'),
('51320d9f-cdff-551e-9b19-af160115d172', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 26, 26, 'A Hall probe is replaced by one of the same material but twice as thick, with the same current and field. What happens to the Hall voltage?', NULL, 2, 'multiple_choice'::answer_type, 'It halves', NULL, false, NULL, false, NULL, 'V_H = BI/ntq ∝ 1/t, so doubling the thickness halves the Hall voltage. Mark scheme (3 marks). C1: V_H = BI/ntq. C1: inverse with t. A1: A (It halves).', 3, NULL, NULL),
('6a772775-f21a-5173-9d5b-f9945ca2826f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 27, 27, 'A semiconductor slice 5.0 mm wide and 0.20 mm thick carries 5.0 mA and has 2.0 × 10²¹ carriers per m³. Calculate the drift speed of the carriers. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '15.63', 'm s⁻¹', false, NULL, false, NULL, 'A = 5.0 × 10⁻³ × 0.20 × 10⁻³ = 1.0 × 10⁻⁶ m². v = I/(nAq) = 5.0 × 10⁻³ ÷ (2.0 × 10²¹ × 1.0 × 10⁻⁶ × 1.60 × 10⁻¹⁹) = 15.6 m s⁻¹. Mark scheme (3 marks). C1: cross-sectional area. C1: v = I/(nAq). A1: v = 15.6 m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 276" role="img" aria-labelledby="fg14b9a164-t fg14b9a164-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg14b9a164-t">Semiconductor slice</title><desc id="fg14b9a164-d">A semiconductor slice 5.0 mm wide and 0.20 mm thick carrying 5.0 mA, with 2.0 × 10²¹ carriers per m³.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I = 5.0 mA</text><polygon points="92,80 95,86.3 89,86.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="92" y1="84.9" x2="92" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="92,170 89,163.7 95,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="86" y="125" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">5.0 mm</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thickness 0.20 mm</text><text x="110" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">2.0 × 10²¹ carriers per m³</text></svg>', 'A semiconductor slice 5.0 mm wide and 0.20 mm thick carrying 5.0 mA, with 2.0 × 10²¹ carriers per m³.'),
('13f142b4-248c-56e4-9ad1-8c5946a3496a', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 28, 28, 'Carriers drift at 15.6 m s⁻¹ through a semiconductor slice in a field of 0.25 T. Calculate the Hall field E_H.', NULL, 2, 'numeric'::answer_type, '3.9', 'V m⁻¹', false, NULL, false, NULL, 'E_H = vB = 15.6 × 0.25 = 3.9 V m⁻¹. Mark scheme (3 marks). M1: qE_H = Bqv. C1: E_H = vB. A1: E_H = 3.9 V m⁻¹.', 3, NULL, NULL),
('c693f453-a45a-5132-8988-7e27785fedbf', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 29, 29, 'Two Hall probes have the same size and current. Probe A has 100 times as many charge carriers per m³ as probe B. What is (Hall voltage of A) ÷ (Hall voltage of B)?', NULL, 2, 'multiple_choice'::answer_type, '1/100', NULL, false, NULL, false, NULL, 'V_H = BI/ntq ∝ 1/n, so 100 times the carrier density gives 1/100 of the voltage. Mark scheme (3 marks). C1: V_H = BI/ntq. C1: inverse with n. A1: D (1/100).', 3, NULL, NULL),
('03553b4b-9f29-5d62-bddc-84a56bf9c74e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 30, 30, 'A wire of cross-sectional area 1.0 × 10⁻⁶ m² carries 1.0 A, and its electrons drift at 1.0 × 10⁻⁴ m s⁻¹. Calculate the number of free electrons per m³. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '6.25e28', 'm⁻³', false, NULL, false, NULL, 'n = I/(Avq) = 1.0 ÷ (1.0 × 10⁻⁶ × 1.0 × 10⁻⁴ × 1.60 × 10⁻¹⁹) = 6.25 × 10²⁸ m⁻³. Mark scheme (3 marks). C1: I = nAvq. C1: rearranged. A1: n = 6.25 × 10²⁸ m⁻³.', 3, NULL, NULL),
('c0abfe75-b2bd-5075-be90-2bdfac9d5845', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 31, 31, 'A Hall probe reads 3.0 mV when its face is at right angles to a field. It is then turned so that the normal to its face is at 40° to the field. Calculate the new reading, in mV.', NULL, 2, 'numeric'::answer_type, '2.298 mV', 'mV', false, NULL, false, NULL, 'Only the perpendicular component B cos 40° acts: V = 3.0 × cos 40° = 2.30 mV. Mark scheme (4 marks). M1: perpendicular component. C1: × cos 40°. C1: value. A1: V_H = 2.30 mV.', 4, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 340 230" role="img" aria-labelledby="fg1c0b070f-t fg1c0b070f-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg1c0b070f-t">Hall probe turned</title><desc id="fg1c0b070f-d">Side view: a uniform field across the page and a flat Hall probe seen edge-on; the normal to its face is turned to 40° from the field direction.</desc><line x1="16" y1="40" x2="319.1" y2="40" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,40 317.7,43 317.7,37" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="77.5" x2="319.1" y2="77.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,77.5 317.7,80.5 317.7,74.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="115" x2="319.1" y2="115" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,115 317.7,118 317.7,112" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="152.5" x2="319.1" y2="152.5" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,152.5 317.7,155.5 317.7,149.5" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="16" y1="190" x2="319.1" y2="190" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="324,190 317.7,193 317.7,187" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="211.1" y1="164" x2="128.9" y2="66" style="stroke:currentColor;stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="128.9" cy="66" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="211.1" cy="164" r="5" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><circle cx="170" cy="115" r="2.6" style="fill:currentColor;stroke:none"/><line x1="170" y1="115" x2="226.5" y2="67.6" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:5 3"/><polygon points="231.3,63.6 227.5,71.7 222.6,65.9" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="241.3" y="58.8" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">normal</text><path d="M204,115 A34,34 0 0,0 196,93.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="209.5" y="96.2" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">40°</text><text x="170" y="220" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">Hall probe (face at an angle)</text></svg>', 'Side view: a uniform field across the page and a flat Hall probe seen edge-on; the normal to its face is turned to 40° from the field direction.'),
('9c44047a-2deb-5092-bc48-832c72711fe2', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 32, 32, 'Identical currents flow along an n-type and a p-type semiconductor slice in the same field. How do the Hall voltages compare?', NULL, 2, 'multiple_choice'::answer_type, 'They have opposite polarities, because the carriers have opposite signs', NULL, false, NULL, false, NULL, 'Holes and electrons moving to give the same current are pushed to the same face but carry opposite charges. Mark scheme (4 marks). C1: same side deflection. C1: opposite charge. C1: opposite polarity. A1: B (They have opposite polarities, because the carriers have opposite signs).', 4, NULL, NULL),
('95de940f-e04f-5c90-b78c-4e408a55ce96', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 33, 33, 'Copper has density 8960 kg m⁻³ and molar mass 0.0635 kg mol⁻¹, with one free electron per atom. Calculate the number of free electrons per m³. Take N_A = 6.02 × 10²³ mol⁻¹.', NULL, 2, 'numeric'::answer_type, '8.494e28', 'm⁻³', false, NULL, false, NULL, 'n = ρN_A/M = 8960 × 6.02 × 10²³ ÷ 0.0635 = 8.49 × 10²⁸ m⁻³. Mark scheme (3 marks). C1: moles per m³. C1: × N_A. A1: n = 8.49 × 10²⁸ m⁻³.', 3, NULL, NULL),
('229751ed-9008-5e87-b9d8-37caa68df6fc', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 34, 34, 'A sodium strip (2.5 × 10²⁸ free electrons per m³) is 0.050 mm thick and carries 1.0 A in a field of 1.0 T. Calculate the Hall voltage, in µV. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '5 uV', 'µV', false, NULL, false, NULL, 'V_H = 1.0 × 1.0 ÷ (2.5 × 10²⁸ × 0.050 × 10⁻³ × 1.60 × 10⁻¹⁹) = 5.0 × 10⁻⁶ V. In µV: 5.0 × 10⁻⁶ × 10⁶ = 5.0. Mark scheme (3 marks). C1: V_H = BI/ntq. C1: conversion. A1: V_H = 5.0 µV.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 296" role="img" aria-labelledby="fgffaa64bd-t fgffaa64bd-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgffaa64bd-t">Sodium strip</title><desc id="fgffaa64bd-d">A sodium strip 0.050 mm thick with 2.5 × 10²⁸ free electrons per m³, carrying 1.0 A in a 1.0 T field into the page.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I = 1.0 A</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thickness 0.050 mm</text><text x="110" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">2.5 × 10²⁸ free electrons per m³</text><line x1="20" y1="272" x2="28" y2="280" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="280" x2="28" y2="272" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="276" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 1.0 T</text></svg>', 'A sodium strip 0.050 mm thick with 2.5 × 10²⁸ free electrons per m³, carrying 1.0 A in a 1.0 T field into the page.'),
('b184a41d-7b20-5661-9b24-91762d2479eb', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 35, 35, 'Why must a Hall probe be calibrated before use?', NULL, 2, 'multiple_choice'::answer_type, 'Its carrier density and thickness are not known accurately, and its output can vary with temperature', NULL, false, NULL, false, NULL, 'Calibration in a known field gives the voltage per unit B directly. Mark scheme (3 marks). C1: n and t uncertain. C1: compare with known field. A1: C (Its carrier density and thickness are not known accurately, and its output can vary with temperature).', 3, NULL, NULL),
('89f1ad6c-63f0-51ef-bdd3-50c68363482e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 36, 36, 'A Hall probe gives 1.0 mV in a field of 10 mT. In the Earth''s field it gives 5.0 µV. Calculate the Earth''s field, in µT.', NULL, 2, 'numeric'::answer_type, '50 uT', 'µT', false, NULL, false, NULL, 'B ∝ V_H: B = 10 × 10⁻³ × 5.0 × 10⁻⁶ ÷ 1.0 × 10⁻³ = 5.0 × 10⁻⁵ T. In µT: 5.0 × 10⁻⁵ × 10⁶ = 50. Mark scheme (3 marks). C1: proportionality. C1: conversion. A1: B = 50 µT.', 3, NULL, NULL),
('fdfdabe3-4581-516b-95d8-cff4c1fe0bfb', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 37, 37, 'A germanium Hall probe has 1.0 × 10²² carriers per m³ and is 0.50 mm thick. Calculate the current needed to give a Hall voltage of 1.0 mV in a field of 0.20 T, in mA. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '4 mA', 'mA', false, NULL, false, NULL, 'I = V_H n t q ÷ B = 1.0 × 10⁻³ × 1.0 × 10²² × 0.50 × 10⁻³ × 1.60 × 10⁻¹⁹ ÷ 0.20 = 4.0 × 10⁻³ A. In mA: 4.0 × 10⁻³ × 1000 = 4.0. Mark scheme (4 marks). C1: rearranged. C1: substitution. C1: conversion. A1: I = 4.0 mA.', 4, NULL, NULL),
('1bc16681-561d-5fdd-80fd-34db170b863d', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 38, 38, 'Which change does NOT alter the Hall voltage of a probe?', NULL, 2, 'multiple_choice'::answer_type, 'Making the slice wider, with the same thickness, current and field', NULL, false, NULL, false, NULL, 'V_H = BI/ntq does not contain the width: a wider slice has a smaller drift speed but a larger width. Mark scheme (3 marks). C1: V_H independent of width. C1: v falls as width rises. A1: A (Making the slice wider, with the same thickness, current and field).', 3, NULL, NULL),
('5bfca80e-3d03-565c-95db-a1420c26c7e6', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 39, 39, 'Calculate (Hall voltage in a semiconductor with 1.0 × 10²² carriers per m³) ÷ (Hall voltage in copper with 8.5 × 10²⁸ carriers per m³), for the same size, current and field.', NULL, 2, 'numeric'::answer_type, '8.5e6', NULL, false, NULL, false, NULL, 'V_H ∝ 1/n: ratio = 8.5 × 10²⁸ ÷ 1.0 × 10²² = 8.5 × 10⁶. Mark scheme (3 marks). C1: V_H ∝ 1/n. C1: ratio. A1: ratio = 8.5 × 10⁶.', 3, NULL, NULL),
('272e5d0f-33aa-503c-80ca-42c45913cf58', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 40, 40, 'In a Hall probe, the Hall field is 4.0 V m⁻¹. Calculate the electric force on a carrier of charge e, in units of 10⁻¹⁹ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '6.4', '10⁻¹⁹ N', false, NULL, false, NULL, 'F = eE_H = 1.60 × 10⁻¹⁹ × 4.0 = 6.40 × 10⁻¹⁹ N. Mark scheme (3 marks). C1: F = qE. C1: value. A1: F = 6.4 × 10⁻¹⁹ N.', 3, NULL, NULL),
('50e72060-2b19-583c-932f-3558ad4e9b8f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 41, 41, 'Across which faces of a rectangular Hall probe is the Hall voltage measured?', NULL, 2, 'multiple_choice'::answer_type, 'The pair of faces at right angles to both the current and the magnetic field', NULL, false, NULL, false, NULL, 'The carriers are deflected along the direction of I × B. Mark scheme (3 marks). C1: perpendicular to I. C1: perpendicular to B. A1: D (The pair of faces at right angles to both the current and the magnetic field).', 3, NULL, NULL),
('1a60651a-5c32-51c1-baeb-b313990d7b5f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 42, 42, 'Electrons drift at 1.5 × 10⁻⁴ m s⁻¹ in a copper strip at right angles to a field of 0.80 T. Calculate the magnetic force on one electron, in units of 10⁻²³ N. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '1.92', '10⁻²³ N', false, NULL, false, NULL, 'F = Bev = 0.80 × 1.60 × 10⁻¹⁹ × 1.5 × 10⁻⁴ = 1.92 × 10⁻²³ N. Mark scheme (3 marks). C1: F = Bqv. C1: value. A1: F = 1.92 × 10⁻²³ N.', 3, NULL, NULL),
('6e661436-b08d-5533-99d1-2c7929c9b4e5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 43, 43, '(a) Starting from qE_H = Bqv and I = nAvq, show that the Hall voltage across a slice of width d and thickness t is V_H = BI/ntq. (b) Calculate V_H for a slice with 1.5 × 10²² carriers per m³, thickness 0.30 mm, current 8.0 mA and field 0.60 T, in mV. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '6.667 mV', 'mV', false, NULL, false, NULL, '(a) E_H = V_H/d = vB, and v = I/(nAq) = I/(ndtq), so V_H = Bvd = BI/(ntq). (b) V_H = 0.60 × 8.0 × 10⁻³ ÷ (1.5 × 10²² × 0.30 × 10⁻³ × 1.60 × 10⁻¹⁹) = 0.00667 V. In mV: 0.006667 × 1000 = 6.67. Mark scheme (6 marks). M1: E_H = V_H/d = vB. M1: v = I/(nAq), A = dt. B1: result shown. C1: substitution. C1: conversion. A1: V_H = 6.67 mV.', 6, NULL, NULL),
('0eba0d84-cce8-58e0-8ba1-7c2bc5451cdb', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 44, 44, 'A Hall probe 0.20 mm thick carries 10 mA. Readings: B/T = 0.10, 0.20, 0.30, 0.40 and V_H/mV = 1.1, 2.2, 3.3, 4.4. (a) Calculate the gradient of the V_H–B graph. (b) Use the gradient to calculate the number of charge carriers per m³. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '2.841e22', 'm⁻³', false, NULL, false, NULL, '(a) Gradient = (4.4 − 1.1) × 10⁻³ ÷ (0.40 − 0.10) = 0.0110 V T⁻¹. (b) Gradient = I/(ntq), so n = I ÷ (gradient × t × q) = 10 × 10⁻³ ÷ (0.01100 × 0.20 × 10⁻³ × 1.60 × 10⁻¹⁹) = 2.84 × 10²² m⁻³. Mark scheme (5 marks). C1: gradient. M1: gradient = I/(ntq). C1: rearranged. C1: value. A1: n = 2.84 × 10²² m⁻³.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 410" role="img" aria-labelledby="fg463d51a3-t fg463d51a3-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg463d51a3-t">Hall voltage against flux density</title><desc id="fg463d51a3-d">Table and graph of Hall voltage against flux density for a probe 0.20 mm thick carrying 10 mA: B = 0.10, 0.20, 0.30, 0.40 T give V_H = 1.1, 2.2, 3.3, 4.4 mV, a straight line through the origin.</desc><g transform="translate(0,0)"><rect x="126.8" y="8" width="146.4" height="140" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><rect x="126.8" y="8" width="146.4" height="28" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="156.2" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">B / T</text><text x="229.4" y="22" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V_H / mV</text><line x1="185.5" y1="8" x2="185.5" y2="148" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="126.8" y1="36" x2="273.2" y2="36" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="156.2" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.10</text><text x="229.4" y="50" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">1.1</text><line x1="126.8" y1="64" x2="273.2" y2="64" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="156.2" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.20</text><text x="229.4" y="78" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">2.2</text><line x1="126.8" y1="92" x2="273.2" y2="92" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="156.2" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.30</text><text x="229.4" y="106" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">3.3</text><line x1="126.8" y1="120" x2="273.2" y2="120" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="156.2" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.40</text><text x="229.4" y="134" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">4.4</text></g><g transform="translate(0,160)"><line x1="24" y1="34" x2="24" y2="202" style="stroke:var(--fig-grid,#d1d5db);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="103.6" y1="34" x2="103.6" y2="2