Color;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="24" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0</text><line x1="103.6" y1="202" x2="103.6" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="103.6" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.1</text><line x1="183.1" y1="202" x2="183.1" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="183.1" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.2</text><line x1="262.7" y1="202" x2="262.7" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="262.7" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.3</text><line x1="342.2" y1="202" x2="342.2" y2="206" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="342.2" y="214" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">0.4</text><line x1="20" y1="202" x2="24" y2="202" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="202" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">0</text><line x1="20" y1="168.4" x2="24" y2="168.4" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="168.4" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">1</text><line x1="20" y1="134.8" x2="24" y2="134.8" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="134.8" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">2</text><line x1="20" y1="101.2" x2="24" y2="101.2" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="101.2" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">3</text><line x1="20" y1="67.6" x2="24" y2="67.6" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="67.6" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4</text><line x1="20" y1="34" x2="24" y2="34" style="stroke:currentColor;stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="17" y="34" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">5</text><text x="203" y="234" font-size="14" text-anchor="middle" dominant-baseline="central" style="fill:currentColor">B / T</text><text x="20" y="14" font-size="14" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H / mV</text><line x1="99.6" y1="161" x2="107.6" y2="169" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="99.6" y1="169" x2="107.6" y2="161" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="179.1" y1="124.1" x2="187.1" y2="132.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="179.1" y1="132.1" x2="187.1" y2="124.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258.7" y1="87.1" x2="266.7" y2="95.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="258.7" y1="95.1" x2="266.7" y2="87.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="338.2" y1="50.2" x2="346.2" y2="58.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="338.2" y1="58.2" x2="346.2" y2="50.2" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/></g></svg>', 'Table and graph of Hall voltage against flux density for a probe 0.20 mm thick carrying 10 mA: B = 0.10, 0.20, 0.30, 0.40 T give V_H = 1.1, 2.2, 3.3, 4.4 mV, a straight line through the origin.'),
('2148cf70-f007-503e-b22a-6925a33442f8', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 45, 45, 'Two Hall probes are each 0.10 mm thick and carry 0.10 A in a field of 0.50 T. One is copper (8.5 × 10²⁸ electrons per m³) and the other indium antimonide (2.0 × 10²² carriers per m³). (a) Calculate the Hall voltage for copper. (b) Calculate the Hall voltage for indium antimonide, in mV. (c) Explain which is more suitable for a practical probe. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '156.2 mV', 'mV', false, NULL, false, NULL, '(a) V_Cu = 0.50 × 0.10 ÷ (8.5 × 10²⁸ × 0.10 × 10⁻³ × 1.60 × 10⁻¹⁹) = 3.68 × 10⁻⁸ V. (b) V_InSb = 0.50 × 0.10 ÷ (2.0 × 10²² × 0.10 × 10⁻³ × 1.60 × 10⁻¹⁹) = 0.156 V. In mV: 0.1562 × 1000 = 156. (c) Indium antimonide: its voltage is millions of times larger and easy to measure. Mark scheme (6 marks). C1: copper value. C1: InSb value. C1: conversion. B1: semiconductor much larger V_H. B1: easily measured. A1: V_H = 156 mV.', 6, NULL, NULL),
('60b7d77d-a91d-53b9-95eb-d8513bdcd30e', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 46, 46, 'A semiconductor slice is 4.0 mm wide and 0.25 mm thick, carries 2.0 mA and has 5.0 × 10²¹ carriers per m³. It is in a field of 0.40 T. (a) Calculate the drift speed of the carriers. (b) Calculate the Hall field. (c) Calculate the Hall voltage, in mV. Give only the answer to (c). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '4 mV', 'mV', false, NULL, false, NULL, '(a) v = 2.0 × 10⁻³ ÷ (5.0 × 10²¹ × 4.0 × 10⁻³ × 0.25 × 10⁻³ × 1.60 × 10⁻¹⁹) = 2.50 m s⁻¹. (b) E_H = vB = 2.500 × 0.40 = 1.00 V m⁻¹. (c) V_H = E_H × width = 1.000 × 4.0 × 10⁻³ = 0.00400 V. In mV: 0.004000 × 1000 = 4.00. Mark scheme (5 marks). C1: v = I/(nAq). C1: E_H = vB. C1: V_H = E_H d. C1: conversion. A1: V_H = 4.00 mV.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 296" role="img" aria-labelledby="fg982fb5d4-t fg982fb5d4-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg982fb5d4-t">Semiconductor slice</title><desc id="fg982fb5d4-d">A semiconductor slice 4.0 mm wide and 0.25 mm thick carrying 2.0 mA, with 5.0 × 10²¹ carriers per m³, in a 0.40 T field into the page.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I = 2.0 mA</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><polygon points="92,80 95,86.3 89,86.3" style="fill:var(--fig-muted,#6b7280);stroke:none"/><line x1="92" y1="84.9" x2="92" y2="165.1" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="92,170 89,163.7 95,163.7" style="fill:var(--fig-muted,#6b7280);stroke:none"/><text x="86" y="125" font-size="12" text-anchor="end" dominant-baseline="central" style="fill:currentColor">4.0 mm</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thickness 0.25 mm</text><text x="110" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">5.0 × 10²¹ carriers per m³</text><line x1="20" y1="272" x2="28" y2="280" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="280" x2="28" y2="272" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="276" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.40 T</text></svg>', 'A semiconductor slice 4.0 mm wide and 0.25 mm thick carrying 2.0 mA, with 5.0 × 10²¹ carriers per m³, in a 0.40 T field into the page.'),
('a3155a14-9eb3-534c-82e1-addc16cf2d6b', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 47, 47, 'A calibrated Hall probe gives 30 mV in a test field of 1.0 mT. Outdoors, it reads 1.4 mV when held to measure the vertical component of the Earth''s field and 0.60 mV for the horizontal component. (a) Calculate both components. (b) Calculate the total field, in µT. (c) Calculate the angle of dip. Give only the answer to (c).', NULL, 3, 'numeric'::answer_type, '66.8', '°', false, NULL, false, NULL, '(a) B_v = 1.4 ÷ 30 × 1.0 × 10⁻³ = 4.67 × 10⁻⁵ T; B_h = 0.60 ÷ 30 × 1.0 × 10⁻³ = 2.0 × 10⁻⁵ T. (b) B = √((4.667 × 10⁻⁵)² + (2.0 × 10⁻⁵)²) = 5.08 × 10⁻⁵ T, which is 50.8 µT. (c) tan θ = 1.4 ÷ 0.60, so θ = tan⁻¹ 2.333 = 66.8°. Mark scheme (6 marks). C1: calibration factor. C1: components. C1: total field. M1: tan dip = B_v/B_h. C1: angle. A1: dip = 66.8°.', 6, NULL, NULL),
('a7e10342-a2ad-57b1-bf80-2516ff1ae062', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 48, 48, 'A semiconductor Hall probe gives 5.0 mV in a certain field at room temperature. When it warms up, its carrier density increases by 20 %. (a) Explain why the Hall voltage changes. (b) Calculate the new Hall voltage, in mV, if B and I are unchanged. (c) Suggest why probes are recalibrated regularly. Give only the answer to (b).', NULL, 3, 'numeric'::answer_type, '4.167 mV', 'mV', false, NULL, false, NULL, '(a) V_H = BI/ntq, so V_H ∝ 1/n. (b) V_H = 5.0 ÷ 1.20 = 4.17 mV. (c) Temperature changes alter n, so the voltage for a given B drifts. Mark scheme (5 marks). B1: V_H ∝ 1/n. C1: ÷ 1.20. C1: value. B1: temperature dependence. A1: V_H = 4.17 mV.', 5, NULL, NULL),
('573f214a-6de1-5106-a066-b8bee63fef91', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 49, 49, 'A p-type semiconductor slice 0.15 mm thick carries 6.0 mA in a field of 0.30 T and gives a Hall voltage of 2.4 mV. (a) Explain how the polarity of the Hall voltage shows that the carriers are positive holes. (b) Calculate the density of holes. Give only the answer to (b). Take e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '3.125e22', 'm⁻³', false, NULL, false, NULL, '(a) Positive holes moving along the current are pushed by the magnetic force to the same face that electrons would reach, but they make that face positive rather than negative. (b) p = BI/(V_H t e) = 0.30 × 6.0 × 10⁻³ ÷ (2.4 × 10⁻³ × 0.15 × 10⁻³ × 1.60 × 10⁻¹⁹) = 3.13 × 10²² m⁻³. Mark scheme (6 marks). B1: same side deflection. B1: opposite polarity for positive carriers. M1: rearranged V_H = BI/ntq. C1: substitution. C1: value. A1: p = 3.13 × 10²² m⁻³.', 6, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 296" role="img" aria-labelledby="fg65961815-t fg65961815-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg65961815-t">p-type slice</title><desc id="fg65961815-d">A p-type semiconductor slice 0.15 mm thick carrying 6.0 mA in a 0.30 T field into the page gives a Hall voltage of 2.4 mV.</desc><rect x="110" y="80" width="210" height="90" rx="0" style="stroke:currentColor;stroke-width:2.0;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><line x1="122" y1="125" x2="301.7" y2="125" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.6;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="308,125 299.8,128.8 299.8,121.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="215" y="112" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:var(--fig-accent-2,#b45309)">I = 6.0 mA</text><circle cx="255" cy="80" r="2.6" style="fill:currentColor;stroke:none"/><circle cx="255" cy="170" r="2.6" style="fill:currentColor;stroke:none"/><line x1="255" y1="80" x2="255" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="40" x2="380" y2="40" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="170" x2="255" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="255" y1="210" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="40" x2="380" y2="113" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="380" y1="137" x2="380" y2="210" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><circle cx="380" cy="125" r="12" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="380" y="125.5" font-size="12" text-anchor="middle" dominant-baseline="central" style="fill:currentColor;font-weight:600">V</text><text x="398" y="125" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">V_H</text><text x="110" y="236" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">thickness 0.15 mm</text><text x="110" y="256" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">Hall voltage 2.4 mV</text><line x1="20" y1="272" x2="28" y2="280" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="20" y1="280" x2="28" y2="272" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="36" y="276" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 0.30 T</text></svg>', 'A p-type semiconductor slice 0.15 mm thick carrying 6.0 mA in a 0.30 T field into the page gives a Hall voltage of 2.4 mV.'),
('0d310391-b460-5009-a53f-c1140e0a6e65', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', 'a672dd4c-ca86-419b-a02b-af95771ed387', 'a-level', '25.4', '9702 coursebook 25.4 · The Hall effect', 50, 50, 'A long solenoid has 3000 turns per metre and carries 2.0 A, so that B = µ₀nI. A Hall probe inside it has 1.0 × 10²² carriers per m³, is 0.20 mm thick and carries 20 mA. (a) Calculate the field in the solenoid. (b) Calculate the expected Hall voltage, in mV. Give only the answer to (b). Take µ₀ = 4π × 10⁻⁷ H m⁻¹ and e = 1.60 × 10⁻¹⁹ C.', NULL, 3, 'numeric'::answer_type, '0.4712 mV', 'mV', false, NULL, false, NULL, '(a) B = 4π × 10⁻⁷ × 3000 × 2.0 = 0.00754 T. (b) V_H = 0.007540 × 20 × 10⁻³ ÷ (1.0 × 10²² × 0.20 × 10⁻³ × 1.60 × 10⁻¹⁹) = 4.71 × 10⁻⁴ V. In mV: 4.712 × 10⁻⁴ × 1000 = 0.471. Mark scheme (5 marks). C1: B = µ₀nI. C1: V_H = BI/ntq. C1: substitution. C1: conversion. A1: V_H = 0.471 mV.', 5, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 420 200" role="img" aria-labelledby="fg15b80cac-t fg15b80cac-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg15b80cac-t">Hall probe in a solenoid</title><desc id="fg15b80cac-d">A long solenoid with 3000 turns per metre carrying 2.0 A; a Hall probe 0.20 mm thick with 1.0 × 10²² carriers per m³, carrying 20 mA, sits inside at the middle.</desc><path d="M69.4,50 A6,40 0 0,0 69.4,130" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M69.4,50 A6,40 0 0,1 69.4,130" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M88.1,50 A6,40 0 0,0 88.1,130" style="stroke:var(--fig-muted,#6b7280);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M88.1,50 A6,40 0 0,1 88.1,130" style="stroke:currentColor;stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><path d="M106.9,50 A6,40 0 