('2ce7902d-813b-58f5-b1dd-a5d507684e47', '51320d9f-cdff-551e-9b19-af160115d172', 'It doubles', 'B', false, 1),
('cc3d6b0a-9ac7-576a-8920-d2312376618d', '51320d9f-cdff-551e-9b19-af160115d172', 'It stays the same', 'C', false, 2),
