('299edd92-836d-5437-a5db-d255db103dc8', '9c44047a-2deb-5092-bc48-832c72711fe2', 'They have opposite polarities, because the carriers have opposite signs', 'B', true, 1),
('72771b25-683f-5c50-8de5-7fd2ccf472f0', '9c44047a-2deb-5092-bc48-832c72711fe2', 'Only the n-type gives a Hall voltage', 'C', false, 2),
