('c8008738-3032-592a-89fd-973649895d30', 'b184a41d-7b20-5661-9b24-91762d2479eb', 'The Hall voltage does not depend on B', 'B', false, 1),
('d5881549-be5b-59e0-99c2-0dcb23f0a114', 'b184a41d-7b20-5661-9b24-91762d2479eb', 'Its carrier density and thickness are not known accurately, and its output can vary with temperature', 'C', true, 2),
