INSERT INTO problems (id, chapter_id, topic_id, curriculum_id, topic_code, syllabus_cite, problem_number, "order", question_text, question_image_url, difficulty_level, answer_type, answer_correct, answer_unit, answer_unit_required, answer_tolerance, answer_sign_sensitive, answer_alternates, explanation, points, figure_svg, figure_alt) VALUES
('75b54547-f388-5146-9c76-177281239b4c', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 7, 7, 'What is thermionic emission?', NULL, 1, 'multiple_choice'::answer_type, 'The release of electrons from the surface of a heated metal', NULL, false, NULL, false, NULL, 'Heating gives some free electrons enough energy to escape the metal. Mark scheme (1 mark). B1: C (The release of electrons from the surface of a heated metal).', 1, NULL, NULL),
('f7330765-2856-5c0e-b44f-6f40fe3640c7', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 8, 8, 'In a fine-beam tube, electrons are accelerated from rest through 300 V. Using e/m = 1.76 × 10¹¹ C kg⁻¹, find their speed.', NULL, 1, 'numeric'::answer_type, '1.028e7', 'm s⁻¹', false, NULL, false, NULL, '½mv² = eV gives v = √(2(e/m)V) = √(2 × 1.76 × 10¹¹ × 300) = 1.03 × 10⁷ m s⁻¹. Mark scheme (2 marks). C1: v = √(2(e/m)V). A1: v = 1.03 × 10⁷ m s⁻¹.', 2, NULL, NULL),
('91a682a8-1613-5392-9b51-f3201f8ccced', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 9, 9, 'Cathode rays passing between two charged plates bend towards the positive plate. What does this show?', NULL, 1, 'multiple_choice'::answer_type, 'The rays carry negative charge', NULL, false, NULL, false, NULL, 'Opposite charges attract. Mark scheme (1 mark). B1: A (The rays carry negative charge).', 1, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fga3f9e1ca-t fga3f9e1ca-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fga3f9e1ca-t">Cathode rays between plates</title><desc id="fga3f9e1ca-d">A beam of cathode rays enters midway between two charged parallel plates (top positive) and bends towards the positive plate.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="110,164 107,157.7 113,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="140" y1="56" x2="140" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="140,164 137,157.7 143,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="170" y1="56" x2="170" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="170,164 167,157.7 173,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="200" y1="56" x2="200" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="200,164 197,157.7 203,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="230" y1="56" x2="230" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="230,164 227,157.7 233,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="260" y1="56" x2="260" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="260,164 257,157.7 263,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="290" y1="56" x2="290" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="290,164 287,157.7 293,157.7" style="fill:var(--fig-accent,#1d4ed8);stroke:none"/><line x1="20" y1="110" x2="79.7" y2="110" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="86,110 77.8,113.8 77.8,106.2" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="22" y="96" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">cathode rays</text><polyline points="90,110 97.3,110 104.7,109.8 112,109.6 119.3,109.3 126.7,108.8 134,108.3 141.3,107.7 148.7,107 156,106.2 163.3,105.3 170.7,104.4 178,103.3 185.3,102.1 192.7,100.9 200,99.5 207.3,98.1 214.7,96.5 222,94.9 229.3,93.2 236.7,91.3 244,89.4 251.3,87.4 258.7,85.3 266,83.1 273.3,80.8 280.7,78.5 288,76 295.3,73.4 302.7,70.8 310,68" style="stroke:var(--fig-accent-2,#b45309);stroke-width:2.0;fill:none;stroke-linecap:round;stroke-linejoin:round;stroke-dasharray:6 4"/></svg>', 'A beam of cathode rays enters midway between two charged parallel plates (top positive) and bends towards the positive plate.'),
('e456175e-3fa7-5802-9000-760c092dffbf', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 10, 10, 'An electron is accelerated from rest through 250 V. Calculate the kinetic energy it gains, in units of 10⁻¹⁷ J. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 1, 'numeric'::answer_type, '4', '10⁻¹⁷ J', false, NULL, false, NULL, 'E_k = eV = 1.60 × 10⁻¹⁹ × 250 = 4.00 × 10⁻¹⁷ J (250 eV). Mark scheme (2 marks). C1: E_k = eV. A1: E_k = 4.0 × 10⁻¹⁷ J.', 2, NULL, NULL),
('f3d7e995-334e-52c1-ac2b-8513901bbd67', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 11, 11, 'Thomson found that cathode rays had the same e/m whatever metal the cathode was made of. What did he conclude?', NULL, 1, 'multiple_choice'::answer_type, 'The particles are a common constituent of all atoms', NULL, false, NULL, false, NULL, 'A universal e/m suggests the same particle comes from every element. Mark scheme (1 mark). B1: D (The particles are a common constituent of all atoms).', 1, NULL, NULL),
('8640e6e3-34dd-5091-bd33-d545a47bc0a5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 12, 12, 'Using e = 1.60 × 10⁻¹⁹ C and mₑ = 9.11 × 10⁻³¹ kg, calculate the specific charge e/m of the electron, in units of 10¹¹ C kg⁻¹.', NULL, 1, 'numeric'::answer_type, '1.756', '10¹¹ C kg⁻¹', false, NULL, false, NULL, 'e/m = 1.60 × 10⁻¹⁹ ÷ 9.11 × 10⁻³¹ = 1.76 × 10¹¹ C kg⁻¹. Mark scheme (2 marks). C1: e ÷ m. A1: e/m = 1.76 × 10¹¹ C kg⁻¹.', 2, NULL, NULL),
('bb275a1f-aa01-5656-9791-80c1a452a7e8', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 13, 13, 'Why must the tube in a cathode-ray or fine-beam experiment contain very little gas?', NULL, 1, 'multiple_choice'::answer_type, 'So that the electrons are not stopped or scattered by collisions with gas molecules', NULL, false, NULL, false, NULL, 'At low pressure the mean free path is long enough for a visible beam. Mark scheme (1 mark). B1: B (So that the electrons are not stopped or scattered by collisions with gas molecules).', 1, NULL, NULL),
('cef63e88-b894-5cb2-a512-0ba61feeca9f', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 14, 14, 'A beam of electrons moving at 1.0 × 10⁷ m s⁻¹ is bent into a circle of radius 5.7 cm by a field of 1.0 mT. Deduce e/m, in units of 10¹¹ C kg⁻¹.', NULL, 1, 'numeric'::answer_type, '1.754', '10¹¹ C kg⁻¹', false, NULL, false, NULL, 'e/m = v/(Br) = 1.0 × 10⁷ ÷ (1.0 × 10⁻³ × 0.057) = 1.75 × 10¹¹ C kg⁻¹. Mark scheme (2 marks). C1: e/m = v/(Br). A1: e/m = 1.75 × 10¹¹ C kg⁻¹.', 2, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 260" role="img" aria-labelledby="fg22ce6ebd-t fg22ce6ebd-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg22ce6ebd-t">Electron beam in a circle</title><desc id="fg22ce6ebd-d">An electron beam moving at 1.0 × 10⁷ m s⁻¹ is bent into a circle of radius 5.7 cm by a uniform 1.0 mT field directed into the page.</desc><line x1="30" y1="27.5" x2="38" y2="35.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="35.5" x2="38" y2="27.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="62.5" x2="38" y2="70.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="70.5" x2="38" y2="62.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="97.5" x2="38" y2="105.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="105.5" x2="38" y2="97.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="132.5" x2="38" y