und;stroke-dasharray:6 4"/><polygon points="356,105 348.7,108.4 348.7,101.6" style="fill:var(--fig-accent-2,#b45309);stroke:none"/><text x="120" y="198" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">E = 1.5 × 10⁴ V m⁻¹</text><line x1="120" y1="214" x2="128" y2="222" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="120" y1="222" x2="128" y2="214" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><text x="136" y="218" font-size="12" text-anchor="start" dominant-baseline="central" style="fill:currentColor">B = 5.0 × 10⁻⁴ T</text></svg>', 'Crossed electric and magnetic fields: E = 1.5 × 10⁴ V m⁻¹ between the plates and B = 5.0 × 10⁻⁴ T; the electron beam passes straight through.'),
('86746518-9fb4-52ba-a873-861d881542f5', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 23, 23, 'In an electron gun, why is the anode at a high positive potential relative to the cathode?', NULL, 1, 'multiple_choice'::answer_type, 'To attract and accelerate the emitted electrons towards it', NULL, false, NULL, false, NULL, 'The p.d. does work eV on each electron. Mark scheme (1 mark). B1: C (To attract and accelerate the emitted electrons towards it).', 1, NULL, NULL),
('b40eb97c-3c4f-5fea-948b-82d5849d38ac', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 24, 24, 'In a fine-beam tube, electrons accelerated through 250 V follow a circle of radius 4.4 cm in a field of 1.2 mT. Calculate e/m, in units of 10¹¹ C kg⁻¹, using e/m = 2V/(B²r²).', NULL, 2, 'numeric'::answer_type, '1.794', '10¹¹ C kg⁻¹', false, NULL, false, NULL, 'e/m = 2V/(B²r²) = 2 × 250 ÷ ((1.2 × 10⁻³)² × 0.044²) = 1.79 × 10¹¹ C kg⁻¹. Mark scheme (3 marks). C1: formula. C1: substitution. A1: e/m = 1.79 × 10¹¹ C kg⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 260" role="img" aria-labelledby="fgd635e059-t fgd635e059-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgd635e059-t">Fine-beam tube</title><desc id="fgd635e059-d">In a fine-beam tube, electrons accelerated through 250 V leave the electron gun and follow a circle of radius 4.4 cm in a uniform 1.2 mT field.</desc><line x1="30" y1="27.5" x2="38" y2="35.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="35.5" x2="38" y2="27.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="62.5" x2="38" y2="70.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="70.5" x2="38" y2="62.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="97.5" x2="38" y2="105.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="30" y1="105.5" x2="38" y2="97.5" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-l