('25f70d84-0ac7-5b76-9593-ef9b17ff31ca', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 30, 30, 'An electron beam carries a current of 0.50 mA. Calculate the number of electrons passing a point each second. Take e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '3.125e15', 's⁻¹', false, NULL, false, NULL, 'N = I/e = 0.50 × 10⁻³ ÷ 1.60 × 10⁻¹⁹ = 3.12 × 10¹⁵ s⁻¹. Mark scheme (3 marks). C1: N = I/e. C1: substitution. A1: N = 3.12 × 10¹⁵ s⁻¹.', 3, NULL, NULL),
('451fd2e5-ef88-5ff0-b5db-6672613b0833', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 31, 31, 'Electrons pass undeflected through crossed fields at 3.0 × 10⁷ m s⁻¹. Calculate their kinetic energy, in keV. Take mₑ = 9.11 × 10⁻³¹ kg and e = 1.60 × 10⁻¹⁹ C.', NULL, 2, 'numeric'::answer_type, '2.562', 'keV', false, NULL, false, NULL, 'E_k = 0.5 × 9.11 × 10⁻³¹ × (3.0 × 10⁷)² = 4.10 × 10⁻¹⁶ J. In keV: 4.100 × 10⁻¹⁶ ÷ 1.6 × 10⁻¹⁶ = 2.56. Mark scheme (3 marks). C1: ½mv². C1: conversion to keV. A1: E_k = 2.56 keV.', 3, NULL, NULL),
('8437e2d7-4c60-5bf4-9fa7-829c868ff887', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 32, 32, 'Which observations convinced Thomson that cathode rays were streams of charged particles rather than waves?', NULL, 2, 'multiple_choice'::answer_type, 'They were deflected by electric and magnetic fields in the way expected for negative charges', NULL, false, NULL, false, NULL, 'Deflection by both fields, consistent with F = eE and F = Bev, showed they were charged particles. Mark scheme (4 marks). C1: electric deflection. C1: magnetic deflection. C1: negative charge. A1: B (They were deflected by electric and magnetic fields in the way expected for negative charges).', 4, NULL, NULL),
('fb6b2703-fda9-5713-80d7-6c6025ec03db', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 33, 33, 'Electrons moving at 2.0 × 10⁷ m s⁻¹ pass between plates 5.0 cm long where E = 1.0 × 10⁴ V m⁻¹. Using e/m = 1.76 × 10¹¹ C kg⁻¹, calculate their sideways deflection, in mm.', NULL, 2, 'numeric'::answer_type, '5.5 mm', 'mm', false, NULL, false, NULL, 'a = (e/m)E = 1.76 × 10¹¹ × 1.0 × 10⁴ = 1.76 × 10¹⁵ m s⁻². t = 0.050 ÷ 2.0 × 10⁷ = 2.5 × 10⁻⁹ s. y = ½at² = 0.5 × 1.76 × 10¹⁵ × (2.5 × 10⁻⁹)² = 0.00550 m. In mm: 0.005500 × 1000 = 5.50. Mark scheme (3 marks). C1: a = (e/m)E. C1: y = ½at². A1: y = 5.50 mm.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 400 220" role="img" aria-labelledby="fg5bfa4f00-t fg5bfa4f00-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fg5bfa4f00-t">Electrons between plates</title><desc id="fg5bfa4f00-d">Electrons moving at 2.0 × 10⁷ m s⁻¹ enter midway between plates 5.0 cm long with a field of 1.0 × 10⁴ V m⁻¹ and are deflected towards the positive plate.</desc><rect x="90" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="90" y="170" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="78" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">+</text><text x="78" y="174" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:600">−</text><line x1="110" y1="56" x2="110" y2="159.1" style="stroke:var(--fig-accent,#1d4ed8);stroke-width:0.9;fill:none;stroke-linecap:round;stroke-linejoin:round"/><polygon points="11