('8b2ea2bc-1ade-5737-aac8-5fce583fd24b', '3fd36cc2-d7e7-4424-b4b5-11a4a8b7ac04', '932c79b4-ef68-44f7-9381-87d5ddebfa17', 'a-level', '25.5', '9702 coursebook 25.5 · Discovering the electron', 41, 41, 'In Thomson''s apparatus, plates 3.0 cm apart have a p.d. of 1500 V and the magnetic field is 1.5 mT. Calculate the speed of electrons that pass undeflected.', NULL, 2, 'numeric'::answer_type, '3.333e7', 'm s⁻¹', false, NULL, false, NULL, 'E = 1500 ÷ 0.030 = 5.0 × 10⁴ V m⁻¹. v = E/B = 5.0 × 10⁴ ÷ 1.5 × 10⁻³ = 3.33 × 10⁷ m s⁻¹. Mark scheme (3 marks). C1: E = V/d. C1: v = E/B. A1: v = 3.33 × 10⁷ m s⁻¹.', 3, '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 440 242" role="img" aria-labelledby="fgb3856639-t fgb3856639-d" style="font-family:ui-sans-serif,system-ui,-apple-system,''Segoe UI'',Roboto,Helvetica,Arial,sans-serif;max-width:100%;height:auto"><title id="fgb3856639-t">Thomson''s apparatus</title><desc id="fgb3856639-d">Plates 3.0 cm apart with a p.d. of 1500 V and a magnetic field of 1.5 mT; electrons of one speed pass straight through.</desc><rect x="120" y="42" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><rect x="120" y="160" width="220" height="8" rx="0" style="stroke:currentColor;stroke-width:0.9;fill:var(--fig-fill,rgba(29,78,216,0.10));stroke-linecap:round;stroke-linejoin:round"/><text x="108" y="46" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">+</text><text x="108" y="164" font-size="14" text-anchor="end" dominant-baseline="central" style="fill:currentColor;font-weight:700">−</text><line x1="139.3" y1="68.3" x2="147.3" y2="76.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin:round"/><line x1="139.3" y1="76.3" x2="147.3" y2="68.3" style="stroke:var(--fig-muted,#6b7280);stroke-width:1.4;fill:none;stroke-linecap:round;stroke-linejoin