('ebcbf942-576d-5997-bd5c-d07c1d8c2eac', '75b54547-f388-5146-9c76-177281239b4c', 'The emission of light by a hot gas', 'A', false, 0),
('c4171826-f3da-58d4-8e3f-8d89e0266be0', '75b54547-f388-5146-9c76-177281239b4c', 'The release of electrons when light shines on a metal', 'B', false, 1),
('361e6dd0-c784-5d3c-92ac-489901c81156', '75b54547-f388-5146-9c76-177281239b4c', 'The release of electrons from the surface of a heated metal', 'C', true, 2),
('9eed3329-9d28-58a0-a819-263397b70a23', '75b54547-f388-5146-9c76-177281239b4c', 'The emission of α-particles from a hot source', 'D', false, 3),
('621667c2-8de5-53e9-a745-2528d55869b1', '91a682a8-1613-5392-9b51-f3201f8ccced', 'The rays carry negative charge', 'A', true, 0),
('220f31d1-fc91-5cc4-9b1d-bc4413535994', '91a682a8-1613-5392-9b51-f3201f8ccced', 'The rays carry positive charge', 'B', false, 1),
('b06a775a-e219-5e27-a552-2e1430d089f3', '91a682a8-1613-5392-9b51-f3201f8ccced', 'The rays are uncharged', 'C', false, 2),
('7549a723-98a5-57d6-a095-c4fa69392620', '91a682a8-1613-5392-9b51-f3201f8ccced', 'The rays are electromagnetic waves', 'D', false, 3),
('9d1f8efd-da93-5ee5-923c-f78c88b72964', 'f3d7e995-334e-52c1-ac2b-8513901bbd67', 'Each metal produces a different particle', 'A', false, 0),
('16d53d31-8727-5fc3-876a-31341d76a7b3', 'f3d7e995-334e-52c1-ac2b-8513901bbd67', 'The rays are a type of light', 'B', false, 1),
('400d5bba-4fdb-5f67-9fc9-d86f089c6415', 'f3d7e995-334e-52c1-ac2b-8513901bbd67', 'The particles are positive ions', 'C', false, 2),
('6e3e10fe-5194-5722-8106-f4a5ec850c7e', 'f3d7e995-334e-52c1-ac2b-8513901bbd67', 'The particles are a common constituent of all atoms', 'D', true, 3),
('2b57dd0e-7d4d-5c48-8387-43b8e30eeeac', 'bb275a1f-aa01-5656-9791-80c1a452a7e8', 'So that the glass does not break', 'A', false, 0),
('96bc1e8b-d647-5018-b827-d3eebb410583', 'bb275a1f-aa01-5656-9791-80c1a452a7e8', 'So that the electrons are not stopped or scattered by collisions with gas molecules', 'B', true, 1),
('c49eb264-edb8-5c96-bd3e-03658dcc0ac2', 'bb275a1f-aa01-5656-9791-80c1a452a7e8', 'So that the electrons can be seen more easily', 'C', false, 2),
('d6be6e2a-08b4-5f42-ba7b-abc9ffcaa00c', 'bb275a1f-aa01-5656-9791-80c1a452a7e8', 'Because gas would absorb the magnetic field', 'D', false, 3),
('6e3329f5-ceba-5f4e-9f45-8920aac3ee19', 'ee26e8a8-a7b3-5c08-95fa-07982c22c73b', 'The electrons themselves glow', 'A', false, 0),
('dab8f058-70ec-5ecc-8e77-9cee67d1f5a6', 'ee26e8a8-a7b3-5c08-95fa-07982c22c73b', 'The magnetic field glows', 'B', false, 1),
('d6e27c46-6774-5b59-8f90-2aeb936914dc', 'ee26e8a8-a7b3-5c08-95fa-07982c22c73b', 'The electrons excite atoms of the low-pressure gas, which then emit light', 'C', true, 2),
('6ef394b5-a90e-5ecd-afe9-af324f923a2e', 'ee26e8a8-a7b3-5c08-95fa-07982c22c73b', 'The glass becomes hot', 'D', false, 3),
('094116b1-d70c-578d-b329-1727c44654e1', '9c9b5a65-727b-5d59-a675-f56795565e6e', 'The charges on individual oil drops, which were always multiples of e', 'A', true, 0),
('df2d8c39-dda4-583a-b0e8-8b5df0b81221', '9c9b5a65-727b-5d59-a675-f56795565e6e', 'The mass of the electron', 'B', false, 1),
('89f2e2b0-cf8a-53d9-937a-062d44841d3e', '9c9b5a65-727b-5d59-a675-f56795565e6e', 'The speed of the electron', 'C', false, 2),
('c976b18d-5463-5e5d-885a-e02d257acfea', '9c9b5a65-727b-5d59-a675-f56795565e6e', 'The ratio e/m', 'D', false, 3),
('6841e273-0018-5170-81ea-789975d12ea1', '76c27235-b1f4-5262-ac62-1fa6ecaf8c02', 'The particles are 1800 times heavier than a hydrogen ion', 'A', false, 0),
('37dd11bb-4b14-5ce3-bde6-e7473a3f7a41', '76c27235-b1f4-5262-ac62-1fa6ecaf8c02', 'The particles carry 1800 times more charge', 'B', false, 1),
('1b6a84a2-1ecb-503f-8502-83558af65b1c', '76c27235-b1f4-5262-ac62-1fa6ecaf8c02', 'The particles are hydrogen ions', 'C', false, 2),
('ac7d6262-7d99-5c09-ae42-a85cc363c381', '76c27235-b1f4-5262-ac62-1fa6ecaf8c02', 'The particles are about 1800 times lighter than a hydrogen ion', 'D', true, 3),
('1a4a9158-ebb4-56fe-9cde-0cbc952580d3', '67795533-a97c-566b-836b-73f42f798716', 'A magnetic field alone, measuring the radius', 'A', false, 0),
('a54c13e4-5252-5123-aaa6-2bb8a6529ef1', '67795533-a97c-566b-836b-73f42f798716', 'Crossed electric and magnetic fields adjusted until the beam was undeflected, so v = E/B', 'B', true, 1),
('dc2367bc-cf88-592e-96af-2fe7d82d843c', '67795533-a97c-566b-836b-73f42f798716', 'An electric field alone, measuring the deflection', 'C', false, 2),
('0619c885-cde6-56d9-8451-9a4375bcbc78', '67795533-a97c-566b-836b-73f42f798716', 'A stopwatch and a ruler', 'D', false, 3),
('d3a2998d-7e49-5fa6-aae9-2d982e99aa07', '86746518-9fb4-52ba-a873-861d881542f5', 'To heat the cathode', 'A', false, 0),
('e99bebde-3f89-5c22-b1ed-40d24b3c031a', '86746518-9fb4-52ba-a873-861d881542f5', 'To repel the electrons back to the cathode', 'B', false, 1),
