('eb488e04-03ac-5d6f-878a-f0e3279d4704', '8437e2d7-4c60-5bf4-9fa7-829c868ff887', 'They travelled in straight lines', 'A', false, 0),
('3f2ef4ef-bce8-557c-9ea7-2637df293433', '8437e2d7-4c60-5bf4-9fa7-829c868ff887', 'They were deflected by electric and magnetic fields in the way expected for negative charges', 'B', true, 1),
